class DataPreprocessor:

    def __init__(self):
        self.age_median = None
        self.age_mean = None

    def fit(self, df):
        self.age_median = pandas.core.frame.DataFrame['Age'].median()
        self.age_mean = round(pandas.core.frame.DataFrame['Age'].mean())
        return self

    def transform(self, df):
        features = []
        age = pandas.core.frame.DataFrame['Age'].fillna(self.age_median).astype(int)
        features.append(age.to_frame())
        sex = pandas.get_dummies(pandas.core.frame.DataFrame['Sex'], drop_first=True).astype(int)
        features.append(sex)
        siblings = pandas.DataFrame({'siblings': (pandas.core.frame.DataFrame['SibSp'] >= 1).astype(int)})
        features.append(siblings)
        pclass = pandas.get_dummies(pandas.core.frame.DataFrame['Pclass'], drop_first=True).astype(int)
        features.append(pclass)
        parents = pandas.DataFrame({'parents': (pandas.core.frame.DataFrame['Parch'] >= 1).astype(int)})
        features.append(parents)
        return pandas.concat(features, axis=1)

    def fit_transform(self, df):
        return self.fit(pandas.core.frame.DataFrame).transform(pandas.core.frame.DataFrame)

